using System;using ZiXing;
class Program {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static Mask Image(int width,int height,Func<int,int,bool> ink){var p=new byte[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++)p[y*width+x]=ink(x,y)?(byte)0:(byte)255;return new Mask(width,height,p);}
 static Mask Strip(int gap){return Image(36+gap*2,16,(x,y)=>{int k=x/(12+gap),local=x%(12+gap);if(k>2||local>10||local<1||y<2||y>13)return false;return k==0?(local<=2||y==2||y==7||y==13):k==1?(local<=2||y==2||y==7):(local==y-2||local==13-y);});}
 static void Main(){var blank=Image(8,8,(x,y)=>false);Check(blank.Tight()==null,"blank glyphs have no ink bounds");var left=Image(8,8,(x,y)=>x==3&&y>=2&&y<=5);Check(string.Join(",",left.Tight())=="3,2,1,4","ink bounds preserve top-left image coordinates");Check(Mask.Similarity(left,left)==1,"identical glyphs score one");var shifted=Image(8,8,(x,y)=>x==4&&y>=2&&y<=5);Check(Mask.Similarity(left,shifted)==1,"one-pixel alignment tolerance");var thicker=Image(8,8,(x,y)=>(x==3||x==4)&&y>=2&&y<=5);Check(Math.Abs(Mask.Similarity(left,thicker)-.5)<.0001,"wrong font weight is penalized");var different=Image(8,8,(x,y)=>y==3&&x>=2&&x<=5);Check(Mask.Similarity(left,different)<.3,"different glyph shapes rank below the source");var scaled=left.Normalize(left.Tight(),12,20);Check(Array.TrueForAll(scaled.Pixels,v=>v==0),"normalization fits tight ink without inventing margins");bool rejected=false;try{Mask.Similarity(left,Image(7,8,(x,y)=>true));}catch(ArgumentException){rejected=true;}Check(rejected,"incompatible masks reject comparison");var partsA=Strip(4).SplitIdeographs(3);var partsB=Strip(8).SplitIdeographs(3);Check(partsA!=null&&partsB!=null,"projection segmentation locates character gaps at different tracking");for(int i=0;i<3;i++)Check(Mask.ShapeSimilarity(partsA[i],partsB[i])>.95,"character identity survives changed tracking "+i);Check(Image(30,16,(x,y)=>true).SplitIdeographs(3)==null,"joined solid outlines do not force a character split");Check(Mask.ShapeSimilarity(left,left)==1,"shape score preserves exact matches");Check(Mask.ShapeSimilarity(left,thicker)<.75,"shape score still penalizes the wrong font weight");}
}
